#!/bin/bash
set -e

# --------------------------------------------------------
# plotSim.sh
#
# Plot simulation data generated by:
#   monteCarlo.sh
#   cornerSim.sh
#
# Usage:
#
#   ./plotSim.sh <csv_file>
#
# The script automatically detects:
#   - Monte Carlo data blocks / indices
#   - Process-corner data blocks / corner names
# --------------------------------------------------------

# check arguments
if [ "$#" -ne 1 ]; then
    echo "Usage: $0 <csv_file>"
    exit 1
fi

CSV=$1

if [ ! -f "$CSV" ]; then
    echo "Error: CSV file not found: $CSV"
    exit 1
fi

# check that gnuplot is installed
if ! command -v gnuplot >/dev/null 2>&1; then
    echo "Error: gnuplot is not installed or not in PATH."
    exit 1
fi

# detect simulation type based on filename
BASENAME=$(basename "$CSV")

if [[ "$BASENAME" == *_all_*.csv ]]; then
    SIM_TYPE="corner"

elif [[ "$BASENAME" == *_mc_*.csv ]]; then
    SIM_TYPE="montecarlo"

else

    echo "Could not determine simulation type from filename."
    echo
    echo "Expected:"
    echo "  Monte Carlo : *_mc_*.csv"
    echo "  Corners     : *_all_*.csv"
    echo

    read -p "Simulation type (mc/corner): " TYPE

    case "$TYPE" in
        mc|MC|montecarlo|MONTECARLO)
            SIM_TYPE="montecarlo"
            ;;

        corner|CORNER)
            SIM_TYPE="corner"
            ;;

        *)
            echo "Invalid simulation type."
            exit 1
            ;;
    esac
fi

# find first non-empty file
FIRST_DATA_LINE=$(awk '
    NF > 0 {
        print
        exit
    }
' "$CSV")

if [ -z "$FIRST_DATA_LINE" ]; then
    echo "Error: CSV is empty."
    exit 1
fi

# determine number of columns
NUM_COLS=$(echo "$FIRST_DATA_LINE" | awk '{print NF}')

if [ "$NUM_COLS" -lt 2 ]; then
    echo "Error: CSV does not contain enough columns."
    exit 1
fi


get_indices()
{
    awk '
    BEGIN {
        block_idx = 0
        in_block = 0
    }

    NF == 0 {
        if (in_block) {
            print block_idx
            block_idx++
            in_block = 0
        }
        next
    }

    /^#/ {
        next
    }

    {
        in_block = 1
    }

    END {
        if (in_block)
            print block_idx
    }
    ' "$CSV"
}


get_corner_map()
{
    awk '
    BEGIN {
        block_idx = 0
        in_block = 0
        corner = ""
    }

    NF == 0 {
        if (in_block) {
            if (corner != "")
                print block_idx, corner

            block_idx++
            in_block = 0
            corner = ""
        }
        next
    }

    /^#/ {
        next
    }

    {
        in_block = 1
        corner = $NF
    }

    END {
        if (in_block && corner != "")
            print block_idx, corner
    }
    ' "$CSV" |
    awk '$2 ~ /^(tt|ss|ff|sf|fs)$/'
}

# determine available indices
INDICES=$(get_indices)

if [ -z "$INDICES" ]; then
    echo "Error: no gnuplot data blocks were detected."
    exit 1
fi

NUM_INDICES=$(echo "$INDICES" | wc -l)

# monte-carlo plotting
plot_montecarlo()
{
    echo ""
    echo "========================================"
    echo "Monte Carlo Simulation"
    echo "========================================"
    echo "CSV: $CSV"
    echo "Columns: $NUM_COLS"
    echo "Available indices: $NUM_INDICES"
    echo

    echo "Available gnuplot indices:"
    echo "$INDICES" | sed 's/^/  /'
    echo

    read -p "Plot all runs or select an index? (all/index): " INDEX

    # plot all runs
    if [[ "$INDEX" =~ ^[Aa][Ll][Ll]$ ]]; then

        echo "Plotting all available Monte Carlo runs..."

        GNUPLOT_FILE=$(mktemp)

        {
            echo "set datafile separator ' '"
            echo "set title 'Monte Carlo Simulation - All Runs'"
            echo "set xlabel 'X'"
            echo "set ylabel 'Value'"
            echo "set grid"
            echo "set key outside"

            echo -n "plot "

            FIRST=1

            for ((COL=2; COL<=NUM_COLS; COL++)); do

                TRACE_NUM=$((COL - 1))

                if [ "$FIRST" -eq 0 ]; then
                    echo -n ", "
                fi

                echo -n "for [idx=0:*] '$CSV' index idx using 1:$COL with lines title sprintf('Run %d - Trace $TRACE_NUM', idx)"

                FIRST=0
            done

            echo

        } > "$GNUPLOT_FILE"

        gnuplot -p "$GNUPLOT_FILE"

        rm -f "$GNUPLOT_FILE"

    # plot specific runs
    elif [[ "$INDEX" =~ ^[0-9]+$ ]]; then

        if ! echo "$INDICES" | grep -qx "$INDEX"; then
            echo
            echo "Error: index $INDEX does not exist."
            echo
            echo "Available indices:"
            echo "$INDICES" | sed 's/^/  /'
            exit 1
        fi

        echo "Plotting Monte Carlo index $INDEX..."

        GNUPLOT_FILE=$(mktemp)

        {
            echo "set datafile separator ' '"
            echo "set title 'Monte Carlo Simulation - Index $INDEX'"
            echo "set xlabel 'X'"
            echo "set ylabel 'Value'"
            echo "set grid"
            echo "set key outside"

            echo -n "plot "

            FIRST=1

            for ((COL=2; COL<=NUM_COLS; COL++)); do

                TRACE_NUM=$((COL - 1))

                if [ "$FIRST" -eq 0 ]; then
                    echo -n ", "
                fi

                echo -n "'$CSV' index $INDEX using 1:$COL with lines title 'Trace $TRACE_NUM'"

                FIRST=0
            done

            echo

        } > "$GNUPLOT_FILE"

        gnuplot -p "$GNUPLOT_FILE"

        rm -f "$GNUPLOT_FILE"


    else

        echo "Invalid selection."
        echo "Enter 'all' or one of the available indices."
        exit 1

    fi
}

# corner plotting
plot_corner()
{
    CORNER_MAP=$(get_corner_map)

    if [ -z "$CORNER_MAP" ]; then
        echo
        echo "Error: no process-corner data was detected."
        echo
        echo "Expected the final field of each data block to be one of:"
        echo "  tt ss ff sf fs"
        echo
        exit 1
    fi

    # determine number of corners
    NUM_CORNERS=$(echo "$CORNER_MAP" | wc -l)

    # determine whether final column is the corner name
    CORNER_COLUMN_DETECTED=0

    if echo "$CORNER_MAP" | grep -q .; then
        CORNER_COLUMN_DETECTED=1
        DATA_COLS=$((NUM_COLS - 1))
    else
        DATA_COLS=$NUM_COLS
    fi


    NUM_TRACES=$((DATA_COLS - 1))

    if [ "$NUM_TRACES" -lt 1 ]; then
        echo "Error: no plotable traces found."
        exit 1
    fi


    echo ""
    echo "========================================"
    echo "Process Corner Simulation"
    echo "========================================"
    echo "CSV: $CSV"
    echo "Columns: $NUM_COLS"
    echo "Data traces: $NUM_TRACES"
    echo "Available corners: $NUM_CORNERS"
    echo ""


    #display detected corners/indices
    echo "Detected process corners:"
    echo

    while read -r IDX NAME; do
        printf "  %-4s -> gnuplot index %s\n" "$NAME" "$IDX"
    done <<< "$CORNER_MAP"

    echo

    read -p "Plot all corners or a specific corner? (all/corner): " CORNER

    # plot all detected corners
    if [[ "$CORNER" =~ ^[Aa][Ll][Ll]$ ]]; then

        echo "Plotting all detected process corners..."

        GNUPLOT_FILE=$(mktemp)

        {
            echo "set datafile separator ' '"
            echo "set title 'Process Corner Comparison'"
            echo "set xlabel 'X'"
            echo "set ylabel 'Value'"
            echo "set grid"
            echo "set key outside"

            echo -n "plot "

            FIRST=1

            while read -r IDX CORNER_NAME; do

                for ((COL=2; COL<=DATA_COLS; COL++)); do

                    TRACE_NUM=$((COL - 1))

                    if [ "$FIRST" -eq 0 ]; then
                        echo -n ", "
                    fi

                    echo -n "'$CSV' index $IDX using 1:$COL with lines title '$CORNER_NAME - Trace $TRACE_NUM'"

                    FIRST=0
                done

            done <<< "$CORNER_MAP"

            echo

        } > "$GNUPLOT_FILE"

        gnuplot -p "$GNUPLOT_FILE"

        rm -f "$GNUPLOT_FILE"


    # plot specific corner
    else

        CORNER=$(echo "$CORNER" | tr '[:upper:]' '[:lower:]')

        MATCH=$(echo "$CORNER_MAP" |
            awk -v wanted="$CORNER" '$2 == wanted { print $1; exit }')


        if [ -z "$MATCH" ]; then
            echo
            echo "Error: corner '$CORNER' was not detected."
            echo
            echo "Available corners:"
            echo "$CORNER_MAP" | awk '{print "  " $2 " (index " $1 ")"}'
            exit 1
        fi


        INDEX=$MATCH

        echo "Plotting process corner: $CORNER"
        echo "gnuplot index: $INDEX"
        echo ""


        GNUPLOT_FILE=$(mktemp)

        {
            echo "set datafile separator ' '"
            echo "set title 'Process Corner: $CORNER'"
            echo "set xlabel 'X'"
            echo "set ylabel 'Value'"
            echo "set grid"
            echo "set key outside"

            echo -n "plot "

            FIRST=1

            for ((COL=2; COL<=DATA_COLS; COL++)); do

                TRACE_NUM=$((COL - 1))

                if [ "$FIRST" -eq 0 ]; then
                    echo -n ", "
                fi

                echo -n "'$CSV' index $INDEX using 1:$COL with lines title 'Trace $TRACE_NUM'"

                FIRST=0
            done

            echo

        } > "$GNUPLOT_FILE"

        gnuplot -p "$GNUPLOT_FILE"

        rm -f "$GNUPLOT_FILE"

    fi
}

# run appropriate plotting function
case "$SIM_TYPE" in

    montecarlo)
        plot_montecarlo
        ;;

    corner)
        plot_corner
        ;;

    *)
        echo "Error: unknown simulation type."
        exit 1
        ;;

esac


echo ""
echo "Plot complete."
